//! Fork-owned items split out of `mod.rs` so upstream syncs don't
//! conflict on them (plan 038; generated by script/fork-split-items).

use super::*;
use pretty_assertions::assert_eq;

impl crate::ForkThreadEnvironment for FakeThreadEnvironment {}

impl crate::ForkThreadEnvironment for MultiTerminalEnvironment {}

#[gpui::test]
pub(super) async fn test_repeated_resume_after_failure_does_not_stack(cx: &mut TestAppContext) {
    let ThreadTest {
        model,
        fake,
        thread,
        ..
    } = setup(cx, TestModel::Fake).await;

    thread
        .update(cx, |thread, cx| {
            thread.send(ClientUserMessageId::new(), ["Message 1"], cx)
        })
        .unwrap();
    cx.run_until_parked();
    // A non-retryable error that doesn't trigger compaction.
    let endpoint_error = || {
        LanguageModelCompletionError::from_http_status(
            LanguageModelProviderName::new("fake"),
            http_client::StatusCode::NOT_FOUND,
            "endpoint not found".to_string(),
            None,
        )
    };
    fake.send_last_error(&model, endpoint_error());
    fake.end_last(&model);
    cx.run_until_parked();

    // Two consecutive failed retries (e.g. auto_prompt riding out an outage).
    for _ in 0..2 {
        thread.update(cx, |thread, cx| thread.resume(cx)).unwrap();
        cx.run_until_parked();
        fake.send_last_error(&model, endpoint_error());
        fake.end_last(&model);
        cx.run_until_parked();
    }

    thread.update(cx, |thread, cx| thread.resume(cx)).unwrap();
    cx.run_until_parked();
    let completion = fake.pending_completions().pop().unwrap();
    let resume_turns = completion
        .messages
        .iter()
        .filter(|message| message.string_contents() == "Continue where you left off")
        .count();
    assert_eq!(resume_turns, 1);
}

#[gpui::test]
pub(super) async fn test_title_request_strips_images_for_summary_model_without_image_support(
    cx: &mut TestAppContext,
) {
    let messages = vec![Arc::new(crate::thread::Message::User(
        crate::thread::UserMessage {
            id: ClientUserMessageId::new(),
            content: Arc::from(vec![
                crate::thread::UserMessageContent::Text("What's in this image?".to_string()),
                crate::thread::UserMessageContent::Image(
                    language_model::LanguageModelImage::empty(),
                ),
            ]),
        },
    ))];

    // Fake models default to `supports_images: false`, matching text-only
    // summarization models whose endpoints reject image content parts.
    let fake = cx.update(LanguageModelRegistry::test);
    let model = fake.model("fake");
    let request = crate::thread::build_thread_title_request(
        &acp_v2::SessionId::new("title-test"),
        &messages,
        None,
    );

    let title_task = cx.spawn({
        let model = model.clone();
        async move |cx| crate::stream_thread_title(model, request, &cx).await
    });
    cx.run_until_parked();

    let sent_request = fake.pending_completions().pop().unwrap();
    let mut placeholders = 0;
    for message in &sent_request.messages {
        for content in &message.content {
            assert!(!matches!(content, MessageContent::Image(_)));
            if matches!(content, MessageContent::Text(text) if text.contains("[image omitted")) {
                placeholders += 1;
            }
        }
    }
    assert_eq!(placeholders, 1);

    fake.send_last_text(&model, "Image question\nmore");
    fake.end_last(&model);
    let title = title_task.await.unwrap();
    assert_eq!(title, "Image question");
}

#[gpui::test]
pub(super) async fn test_title_request_keeps_images_for_summary_model_with_image_support(
    cx: &mut TestAppContext,
) {
    let messages = vec![Arc::new(crate::thread::Message::User(
        crate::thread::UserMessage {
            id: ClientUserMessageId::new(),
            content: Arc::from(vec![crate::thread::UserMessageContent::Image(
                language_model::LanguageModelImage::empty(),
            )]),
        },
    ))];

    let fake = cx.update(LanguageModelRegistry::test);
    let model = fake.update_model("fake", |model| model.supports_images = true);
    let request = crate::thread::build_thread_title_request(
        &acp_v2::SessionId::new("title-test"),
        &messages,
        None,
    );

    let title_task = cx.spawn({
        let model = model.clone();
        async move |cx| crate::stream_thread_title(model, request, &cx).await
    });
    cx.run_until_parked();

    let sent_request = fake.pending_completions().pop().unwrap();
    assert!(sent_request.messages.iter().any(|message| {
        message
            .content
            .iter()
            .any(|content| matches!(content, MessageContent::Image(_)))
    }));

    fake.send_last_text(&model, "Title\ngunk");
    fake.end_last(&model);
    title_task.await.unwrap();
}

#[gpui::test]
pub(super) fn test_strip_unsupported_images_replaces_tool_result_images(cx: &mut TestAppContext) {
    let fake = cx.update(LanguageModelRegistry::test);
    let text_model = fake.model("text-model");
    let with_tool_result = LanguageModelRequest {
        messages: vec![LanguageModelRequestMessage {
            role: Role::Assistant,
            content: vec![MessageContent::ToolResult(LanguageModelToolResult {
                tool_use_id: "tool_1".into(),
                tool_name: "screenshot".into(),
                is_error: false,
                content: vec![
                    "some text".into(),
                    language_model::LanguageModelToolResultContent::Image(
                        language_model::LanguageModelImage::empty(),
                    ),
                ],
                output: Some("some text".into()),
            })],
            cache: false,
            reasoning_details: None,
        }],
        ..Default::default()
    };

    let stripped = crate::thread::strip_unsupported_images(&text_model, with_tool_result.clone());
    let MessageContent::ToolResult(tool_result) = &stripped.messages[0].content[0] else {
        panic!("expected tool result");
    };
    assert_eq!(tool_result.content.len(), 2);
    assert!(matches!(
        &tool_result.content[1],
        language_model::LanguageModelToolResultContent::Text(text) if text.contains("[image omitted")
    ));

    let image_model = fake.update_model("image-model", |model| model.supports_images = true);
    let untouched = crate::thread::strip_unsupported_images(&image_model, with_tool_result);
    let MessageContent::ToolResult(tool_result) = &untouched.messages[0].content[0] else {
        panic!("expected tool result");
    };
    assert!(matches!(
        &tool_result.content[1],
        language_model::LanguageModelToolResultContent::Image(_)
    ));
}

#[gpui::test]
pub(super) async fn test_main_turn_strips_images_for_model_without_image_support(
    cx: &mut TestAppContext,
) {
    let ThreadTest {
        model,
        fake,
        thread,
        ..
    } = setup(cx, TestModel::Fake).await;

    // History can contain images even for a text-only model: Thread::send
    // stores content unconditionally (paste happened under an image-capable
    // model, or the message arrived over ACP).
    let send = thread
        .update(cx, |thread, cx| {
            thread.send(
                ClientUserMessageId::new(),
                [
                    UserMessageContent::Text("What's in this image?".to_string()),
                    UserMessageContent::Image(language_model::LanguageModelImage::empty()),
                ],
                cx,
            )
        })
        .unwrap();
    cx.run_until_parked();

    let completion = fake.pending_completions().pop().unwrap();
    let mut placeholders = 0;
    for message in &completion.messages {
        for content in &message.content {
            assert!(!matches!(content, MessageContent::Image(_)));
            if matches!(content, MessageContent::Text(text) if text.contains("[image omitted")) {
                placeholders += 1;
            }
        }
    }
    assert_eq!(placeholders, 1);

    fake.send_text(&model, &completion, "An image");
    fake.end_stream(&model, &completion);
    send.collect::<Vec<_>>().await;
    cx.run_until_parked();
}

