#[gpui::test]
pub(super) async fn test_send_retry_after_capped_on_rate_limit(cx: &mut TestAppContext) {
    let ThreadTest {
        thread,
        model,
        fake,
        ..
    } = setup(cx, TestModel::Fake).await;

    let mut events = thread
        .update(cx, |thread, cx| {
            thread.send(ClientUserMessageId::new(), ["Hello!"], cx)
        })
        .unwrap();
    cx.run_until_parked();

    fake.send_last_text(&model, "Hey,");
    fake.send_last_error(
        &model,
        LanguageModelCompletionError::from_http_status(
            LanguageModelProviderName::new("GLM"),
            http_client::StatusCode::TOO_MANY_REQUESTS,
            "rate limit exceeded".to_string(),
            Some(Duration::from_secs(9428)),
        ),
    );
    fake.end_last(&model);

    // The retry timer must fire at the capped delay (plus jitter), not at the
    // provider's multi-hour hint: advancing only the cap proves the backoff
    // was clamped.
    let max_capped_delay = crate::maximum_retry_delay_with_jitter(crate::thread::MAX_RETRY_AFTER);
    cx.executor().advance_clock(max_capped_delay);
    cx.run_until_parked();

    fake.send_last_text(&model, "there!");
    fake.end_last(&model);
    cx.run_until_parked();

    let mut retry_events = Vec::new();
    while let Some(Ok(event)) = events.next().await {
        match event {
            ThreadEvent::Retry(retry_status) => {
                retry_events.push(retry_status);
            }
            ThreadEvent::Stop(..) => break,
            _ => {}
        }
    }

    assert_eq!(retry_events.len(), 1);
    assert_eq!(retry_events[0].attempt, 1);
    assert!(retry_events[0].duration >= crate::thread::MAX_RETRY_AFTER);
    assert!(retry_events[0].duration <= max_capped_delay);
    thread.read_with(cx, |thread, _cx| {
        assert_eq!(
            thread.to_markdown(),
            indoc! {"
                ## User

                Hello!

                ## Assistant

                Hey,

                [resume]

                ## Assistant

                there!
            "}
        )
    });
}

#[gpui::test]
pub(super) async fn test_subagent_retry_does_not_signal_parent_cancel(cx: &mut TestAppContext) {
    // Regression test: when a subagent is retried (via the retry button), the
    // retry cancels the subagent's current turn and starts a new one. Without
    // the fix, this cancellation propagated to the parent as "User canceled",
    // causing the parent to give up prematurely. The parent should instead keep
    // waiting for the retried subagent turn to complete.
    let fake = init_test(cx);
    cx.update(|cx| {
        cx.update_flags(true, vec!["subagents".to_string()]);
    });

    let fs = FakeFs::new(cx.executor());
    fs.insert_tree(
        "/",
        json!({
            "a": {
                "b.md": "Lorem"
            }
        }),
    )
    .await;
    let project = Project::test(fs.clone(), [path!("/a").as_ref()], cx).await;
    let thread_store = cx.new(|cx| ThreadStore::new(cx));
    let agent =
        cx.update(|cx| NativeAgent::new(thread_store.clone(), Templates::new(), fs.clone(), cx));
    let connection = Rc::new(NativeAgentConnection(agent.clone()));

    let acp_thread = cx
        .update(|cx| {
            connection
                .clone()
                .new_session(project.clone(), PathList::new(&[Path::new("")]), cx)
        })
        .await
        .unwrap();
    let session_id = acp_thread.read_with(cx, |thread, _| thread.session_id().clone());
    let thread = agent.read_with(cx, |agent, _| {
        agent.sessions.get(&session_id).unwrap().thread.clone()
    });
    let model = fake.model("thread");

    thread.update(cx, |thread, cx| {
        thread.set_model(model.clone(), cx);
    });
    cx.run_until_parked();

    // === Start parent turn that spawns a subagent ===
    let send = cx.update(|cx| {
        connection.send_and_wait_for_completion(acp_thread.clone(), vec!["Prompt".into()], cx)
    });
    cx.run_until_parked();
    let request = fake.pending_completions_for(&model).pop().unwrap();
    fake.send_text(&model, &request, "spawning subagent");
    let subagent_tool_input = SpawnAgentToolInput {
        label: "label".to_string(),
        message: "subagent task prompt".to_string(),
        session_id: None,
        model: None,
    };
    let subagent_tool_use = LanguageModelToolUse {
        id: "subagent_1".into(),
        name: SpawnAgentTool::NAME.into(),
        raw_input: serde_json::to_string(&subagent_tool_input).unwrap(),
        input: language_model::LanguageModelToolUseInput::Json(
            serde_json::to_value(&subagent_tool_input).unwrap(),
        ),
        is_input_complete: true,
        thought_signature: None,
    };
    fake.send_event(
        &model,
        &request,
        LanguageModelCompletionEvent::ToolUse(subagent_tool_use),
    );
    fake.end_stream(&model, &request);

    cx.run_until_parked();

    let subagent_session_id = thread.read_with(cx, |thread, cx| {
        thread
            .running_subagent_ids(cx)
            .get(0)
            .expect("subagent thread should be running")
            .clone()
    });
    let subagent_acp_thread = agent.read_with(cx, |agent, _cx| {
        agent
            .sessions
            .get(&subagent_session_id)
            .expect("subagent session should exist")
            .acp_thread
            .upgrade()
            .expect("subagent thread should be alive")
    });

    // Subagent starts working (model is generating, not yet ended)
    fake.send_last_text(&model, "partial work");
    cx.run_until_parked();

    // === Retry the subagent ===
    // This cancels the subagent's current turn and starts a new one.
    // The parent should NOT see this as a cancellation.
    let _retry = subagent_acp_thread.update(cx, |thread, cx| thread.retry(cx));
    cx.run_until_parked();

    // The subagent should still be registered as running in the parent.
    // Before the fix, the parent would have already given up.
    thread.read_with(cx, |thread, cx| {
        assert_eq!(
            thread.running_subagent_ids(cx).len(),
            1,
            "subagent should still be running in parent after retry"
        );
    });

    // Subagent's retry turn produces a response
    let request = fake.pending_completions_for(&model).pop().unwrap();
    fake.send_text(&model, &request, "subagent task response");
    fake.end_stream(&model, &request);

    cx.run_until_parked();

    // Parent model responds to complete its turn
    let request = fake.pending_completions_for(&model).pop().unwrap();
    fake.send_text(&model, &request, "Parent response");
    fake.end_stream(&model, &request);

    // The parent's send should complete successfully (not error out).
    send.await
        .expect("parent turn should complete successfully after subagent retry");

    // Verify the parent's tool call completed (not canceled)
    acp_thread.read_with(cx, |thread, cx| {
        assert_eq!(
            thread.to_markdown(cx),
            indoc! {"
                ## User

                Prompt

                ## Assistant

                spawning subagent

                **Tool Call: label**
                Status: Completed

                subagent task response

                ## Assistant

                Parent response

            "}
        );
    });
}
